function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'NumberContainers' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with NumberContainers() and no arguments.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls to change and find.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 1000000000;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (operations[i] === 'change') {
      if (!Array.isArray(a) || a.length !== 2 || !ok(a[0]) || !ok(a[1])) return 'change takes an index and a number from 1 to 10^9.';
    } else if (operations[i] === 'find') {
      if (!Array.isArray(a) || a.length !== 1 || !ok(a[0])) return 'find takes a number from 1 to 10^9.';
    } else return 'Only change and find can follow the constructor.';
  }
  return null;
}

