class NumberContainers {
  constructor() {
    this.numberAt = new Map();
    this.heaps = new Map();
  }

  change(index, number) {
    if (this.numberAt.get(index) === number) {
      return;
    }
    this.numberAt.set(index, number);
    if (!this.heaps.has(number)) {
      this.heaps.set(number, []);
    }
    this.push(this.heaps.get(number), index);
  }

  find(number) {
    const heap = this.heaps.get(number);
    if (!heap) {
      return -1;
    }
    while (heap.length > 0 && this.numberAt.get(heap[0]) !== number) {
      this.pop(heap);
    }
    return heap.length > 0 ? heap[0] : -1;
  }

  push(heap, index) {
    heap.push(index);
    let child = heap.length - 1;
    while (child > 0 && heap[(child - 1) >> 1] > heap[child]) {
      const parent = (child - 1) >> 1;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  }

  pop(heap) {
    const last = heap.pop();
    if (heap.length === 0) {
      return;
    }
    heap[0] = last;
    let parent = 0;
    for (;;) {
      let smallest = parent;
      for (const child of [2 * parent + 1, 2 * parent + 2]) {
        if (child < heap.length && heap[child] < heap[smallest]) {
          smallest = child;
        }
      }
      if (smallest === parent) {
        return;
      }
      [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
      parent = smallest;
    }
  }
}

