function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const calls = large ? 499 : int(1, 16);
  const indexTop = large ? [20, 200, 1000000000][int(0, 2)] : int(1, 6);
  const numberTop = large ? [3, 30, 1000000000][int(0, 2)] : int(1, 4);
  const indexPool = Array.from({ length: large ? 300 : 6 }, () => int(1, indexTop));
  const numberPool = Array.from({ length: large ? 40 : 4 }, () => int(1, numberTop));
  const pick = pool => pool[Math.floor(rand() * pool.length)];
  const operations = ['NumberContainers'];
  const args = [[]];
  for (let i = 0; i < calls; i++) {
    if (rand() < 0.55) {
      operations.push('change');
      args.push([pick(indexPool), pick(numberPool)]);
    } else {
      operations.push('find');
      args.push([rand() < 0.9 ? pick(numberPool) : int(1, 1000000000)]);
    }
  }
  return [operations, args];
}
